def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    div_rows = [r for r, row in enumerate(grid)
                if len(set(row)) == 1 and row[0] != bg]
    div_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != bg]

    def segments(n, cuts):
        result, start = [], 0
        for cut in cuts:
            if start < cut:
                result.append((start, cut))
            start = cut + 1
        if start < n:
            result.append((start, n))
        return result

    rs, cs = segments(h, div_rows), segments(w, div_cols)
    out = [row[:] for row in grid]

    # Repeat each non-background cell at the same local position in every tile.
    for ri, (r0, r1) in enumerate(rs):
        for ci, (c0, c1) in enumerate(cs):
            for r in range(r0, r1):
                for c in range(c0, c1):
                    value = grid[r][c]
                    if value == bg:
                        continue
                    lr, lc = r - r0, c - c0
                    for tr0, tr1 in rs:
                        for tc0, tc1 in cs:
                            rr, cc = tr0 + lr, tc0 + lc
                            if rr < tr1 and cc < tc1:
                                out[rr][cc] = value
    return out
